WITH flattened_attrs AS (SELECT id, plan, effective_from, currency, tier_limits, tier_prices, discounts, ARRAY_MIN(tier_prices) AS lowest_price, SLICE(tier_limits, 1, 2) AS first_two_limits FROM price_tiers WHERE plan <> 'basic') SELECT currency, APPROX_PERCENTILE(lowest_price, ARRAY(0.25, 0.5, 0.75)) AS lowest_price_quartiles, ROUND(SUM(lowest_price) / NULLIF(COUNT(CASE WHEN plan = 'pro' THEN 1 END), 0), 2) AS lowest_price_per_pro, SORT_ARRAY(COLLECT_SET(plan)) AS plan_list, SUM(CASE WHEN currency = 'USD' THEN lowest_price ELSE 0 END) AS usd_lowest_price, PERCENTILE_APPROX(lowest_price, 0.5) AS lowest_price_p50, SUM(lowest_price) AS total_lowest_price FROM flattened_attrs GROUP BY 1 HAVING PERCENTILE_APPROX(lowest_price, 0.5) > 0 ORDER BY total_lowest_price DESC
